using Microsoft.VisualStudio.TestTools.UnitTesting;
using Moq;
using Payments;

namespace Payments.Tests;

[TestClass]
public class PaymentGatewayTests
{
    private Mock<IPaymentProvider> _providerMock = null!;
    private PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup()
    {
        _providerMock = new Mock<IPaymentProvider>(MockBehavior.Strict);
        _gateway = new PaymentGateway(_providerMock.Object);
    }

    // --- Constructor ---

    [TestMethod]
    public void Constructor_NullProvider_ThrowsArgumentNullException()
    {
        Assert.ThrowsException<ArgumentNullException>(() => new PaymentGateway(null!));
    }

    // --- ChargeAsync: positive cases ---

    [TestMethod]
    public async Task ChargeAsync_ValidRequest_ReturnsSuccessResult()
    {
        var expected = new ChargeResult("ch_123", true);
        _providerMock.Setup(p => p.ProcessChargeAsync("tok_visa", 49.99m))
                     .ReturnsAsync(expected);

        var result = await _gateway.ChargeAsync("tok_visa", 49.99m);

        Assert.AreEqual(expected, result);
        Assert.IsTrue(result.Success);
        _providerMock.Verify(p => p.ProcessChargeAsync("tok_visa", 49.99m), Times.Once);
    }

    [TestMethod]
    public async Task ChargeAsync_MinimumAmount_Succeeds()
    {
        var expected = new ChargeResult("ch_min", true);
        _providerMock.Setup(p => p.ProcessChargeAsync("tok_visa", 0.01m))
                     .ReturnsAsync(expected);

        var result = await _gateway.ChargeAsync("tok_visa", 0.01m);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public async Task ChargeAsync_MaxAllowedAmount_Succeeds()
    {
        var expected = new ChargeResult("ch_max", true);
        _providerMock.Setup(p => p.ProcessChargeAsync("tok_visa", 999_999.99m))
                     .ReturnsAsync(expected);

        var result = await _gateway.ChargeAsync("tok_visa", 999_999.99m);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderDeclinesCharge_ReturnsFailureResult()
    {
        var expected = new ChargeResult("ch_fail", false);
        _providerMock.Setup(p => p.ProcessChargeAsync("tok_declined", 10m))
                     .ReturnsAsync(expected);

        var result = await _gateway.ChargeAsync("tok_declined", 10m);

        Assert.IsFalse(result.Success);
    }

    // --- ChargeAsync: negative / boundary cases ---

    [TestMethod]
    public async Task ChargeAsync_NullToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.ChargeAsync(null!, 10m));
    }

    [TestMethod]
    public async Task ChargeAsync_EmptyToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.ChargeAsync("", 10m));
    }

    [TestMethod]
    public async Task ChargeAsync_WhitespaceToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.ChargeAsync("   ", 10m));
    }

    [TestMethod]
    public async Task ChargeAsync_ZeroAmount_ThrowsArgumentOutOfRangeException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentOutOfRangeException>(
            () => _gateway.ChargeAsync("tok_visa", 0m));
    }

    [TestMethod]
    public async Task ChargeAsync_NegativeAmount_ThrowsArgumentOutOfRangeException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentOutOfRangeException>(
            () => _gateway.ChargeAsync("tok_visa", -5m));
    }

    [TestMethod]
    public async Task ChargeAsync_ExceedsMaxAmount_ThrowsArgumentOutOfRangeException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentOutOfRangeException>(
            () => _gateway.ChargeAsync("tok_visa", 1_000_000m));
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderThrows_PropagatesException()
    {
        _providerMock.Setup(p => p.ProcessChargeAsync("tok_visa", 10m))
                     .ThrowsAsync(new InvalidOperationException("Gateway timeout"));

        await Assert.ThrowsExceptionAsync<InvalidOperationException>(
            () => _gateway.ChargeAsync("tok_visa", 10m));
    }

    // --- RefundAsync: positive cases ---

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessResult()
    {
        var expected = new RefundResult("re_456", true);
        _providerMock.Setup(p => p.ProcessRefundAsync("ch_123"))
                     .ReturnsAsync(expected);

        var result = await _gateway.RefundAsync("ch_123");

        Assert.AreEqual(expected, result);
        Assert.IsTrue(result.Success);
        _providerMock.Verify(p => p.ProcessRefundAsync("ch_123"), Times.Once);
    }

    [TestMethod]
    public async Task RefundAsync_ProviderDeclinesRefund_ReturnsFailureResult()
    {
        var expected = new RefundResult("re_fail", false);
        _providerMock.Setup(p => p.ProcessRefundAsync("ch_old"))
                     .ReturnsAsync(expected);

        var result = await _gateway.RefundAsync("ch_old");

        Assert.IsFalse(result.Success);
    }

    // --- RefundAsync: negative cases ---

    [TestMethod]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.RefundAsync(null!));
    }

    [TestMethod]
    public async Task RefundAsync_EmptyChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.RefundAsync(""));
    }

    [TestMethod]
    public async Task RefundAsync_WhitespaceChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.RefundAsync("  "));
    }

    [TestMethod]
    public async Task RefundAsync_ProviderThrows_PropagatesException()
    {
        _providerMock.Setup(p => p.ProcessRefundAsync("ch_123"))
                     .ThrowsAsync(new InvalidOperationException("Network error"));

        await Assert.ThrowsExceptionAsync<InvalidOperationException>(
            () => _gateway.RefundAsync("ch_123"));
    }

    // --- ProcessWebhook: positive cases ---

    [TestMethod]
    public void ProcessWebhook_ChargeSucceeded_ReturnsHandled()
    {
        var result = _gateway.ProcessWebhook("charge.succeeded", "{\"id\":\"ch_1\"}");

        Assert.IsTrue(result.Handled);
        Assert.AreEqual("Charge confirmed", result.Message);
    }

    [TestMethod]
    public void ProcessWebhook_ChargeFailed_ReturnsHandled()
    {
        var result = _gateway.ProcessWebhook("charge.failed", "{\"id\":\"ch_2\"}");

        Assert.IsTrue(result.Handled);
        Assert.AreEqual("Charge failure recorded", result.Message);
    }

    [TestMethod]
    public void ProcessWebhook_RefundCompleted_ReturnsHandled()
    {
        var result = _gateway.ProcessWebhook("refund.completed", "{\"id\":\"re_1\"}");

        Assert.IsTrue(result.Handled);
        Assert.AreEqual("Refund confirmed", result.Message);
    }

    [TestMethod]
    public void ProcessWebhook_UnknownEvent_ReturnsNotHandled()
    {
        var result = _gateway.ProcessWebhook("dispute.opened", "{\"id\":\"dp_1\"}");

        Assert.IsFalse(result.Handled);
        StringAssert.Contains(result.Message, "dispute.opened");
    }

    // --- ProcessWebhook: negative cases ---

    [TestMethod]
    public void ProcessWebhook_NullEventType_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(
            () => _gateway.ProcessWebhook(null!, "{}"));
    }

    [TestMethod]
    public void ProcessWebhook_EmptyPayload_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(
            () => _gateway.ProcessWebhook("charge.succeeded", ""));
    }

    [TestMethod]
    public void ProcessWebhook_WhitespaceEventType_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(
            () => _gateway.ProcessWebhook("  ", "{}"));
    }
}

using Microsoft.VisualStudio.TestTools.UnitTesting;
using Moq;
using Payments;

namespace Payments.Tests;

[TestClass]
public class PaymentGatewayTests
{
    private Mock<IPaymentProvider> _providerMock = null!;
    private PaymentGateway _gateway = null!;

    [TestInitialize]
